49	class ProducerUsedBufferFinder : public StmtExprVisitor {
50	public:
51	  auto FindProducerusedBuffer(const Stmt &stmt) {
52	    producer_buffers_.clear();
53	    let_var_to_expr_.clear();
54	    std::unordered_set<const BufferNode *> last_producer_buffers_;
55	    for (;;) {
56	      VisitStmt(stmt);
57	      if (producer_buffers_ == last_producer_buffers_) {
58	        break;
59	      }
60	      last_producer_buffers_ = producer_buffers_;
61	    }
62	    return producer_buffers_;
63	  }
64	
65	  void InsertBuffer(const PrimExpr &expr) {
66	    // Find the buffer that is used in the condition
67	    VarUseDefAnalyzer usage(Array<Var>{});
68	    usage(expr);
69	    for (const auto &buffer : usage.buffer_use_count_) {
70	      producer_buffers_.insert(buffer.first);
71	    }
72	    // Also collect buffers through let bindings
73	    CollectBuffersFromExpr(expr);
74	  }
75	
76	  // Collect buffers from expression, following let bindings
77	  void CollectBuffersFromExpr(const PrimExpr &expr) {
78	    PostOrderVisit(expr, [this](const ObjectRef &node) {
79	      if (auto bl = node.as<BufferLoadNode>()) {
80	        producer_buffers_.insert(bl->buffer.get());
81	      } else if (auto var_node = node.as<VarNode>()) {
82	        auto var = tvm::ffi::GetRef<Var>(var_node);
83	        auto it = let_var_to_expr_.find(var.get());
84	        if (it != let_var_to_expr_.end()) {
85	          CollectBuffersFromExpr(it->second);
86	        }
87	      }
88	    });
89	  }
90	
91	  void VisitStmt_(const LetStmtNode *op) final {
92	    let_var_to_expr_[op->var.get()] = op->value;
93	    StmtExprVisitor::VisitStmt_(op);
94	  }
95	
96	  void VisitStmt_(const IfThenElseNode *op) final {
97	    ProducerBufferDetector producer_buffer_detector(producer_buffers_);
98	    producer_buffer_detector(op->then_case);
99	    if (op->else_case.defined()) {
100	      producer_buffer_detector(op->else_case.value());
101	    }
102	    if (producer_buffer_detector.has_producer_buffer_) {
103	      InsertBuffer(op->condition);
104	    }
105	    StmtExprVisitor::VisitStmt_(op);
106	  }
107	
108	  void VisitStmt_(const ForNode *op) final {
109	    ProducerBufferDetector producer_buffer_detector(producer_buffers_);
110	    producer_buffer_detector(op->body);
111	    if (producer_buffer_detector.has_producer_buffer_) {
112	      InsertBuffer(op->min);
113	      InsertBuffer(op->extent);
114	    }
115	    StmtExprVisitor::VisitStmt_(op);
116	  }
117	
118	  void VisitStmt_(const BufferStoreNode *op) final {
119	    if (producer_buffers_.count(op->buffer.get())) {
120	      InsertBuffer(op->value);
121	    }
122	    StmtExprVisitor::VisitStmt_(op);
123	  }
124	
125	  void VisitExpr_(const CallNode *op) final {
126	    if (op->op.same_as(tma_load()) || op->op.same_as(tma_load_im2col())) {
127	      for (auto arg : op->args) {
128	        // Collect buffers from args, including through let bindings
129	        CollectBuffersFromExpr(arg);
130	      }
131	    }
132	  }
133	
134	private:
135	  std::unordered_set<const BufferNode *> producer_buffers_;
136	  std::unordered_map<const VarNode *, PrimExpr> let_var_to_expr_;
137	};
