139	class WarpSpecializedRoleMarker : public StmtVisitor {
140	public:
141	  WarpSpecializedRoleMarker(Map<Var, Buffer> buffer_data_to_buffer)
142	      : buffer_data_to_buffer_(std::move(buffer_data_to_buffer)) {}
143	
144	  void Prepare(const Stmt &stmt) {
145	    ProducerUsedBufferFinder finder;
146	    producer_buffers_ = finder.FindProducerusedBuffer(stmt);
147	  }
148	
149	  Role GetRole(const StmtNode *stmt) const {
150	    auto it = map_.find(stmt);
151	    ICHECK(it != map_.end());
152	    return it->second;
153	  }
154	
155	  Role GetRole(const Stmt &stmt) const { return GetRole(stmt.get()); }
156	
157	  void VisitStmt_(const EvaluateNode *op) final {
158	    Role role = Role::kConsumer;
159	    if (auto call = op->value.as<CallNode>()) {
160	      if (call->op.same_as(tma_load()) || call->op.same_as(tma_load_im2col())) {
161	        role = Role::kProducer;
162	        has_bulk_copy_ = true;
163	      }
164	      if (call->op.same_as(loop_break())) {
165	        role = Role::kBoth;
166	      }
167	    }
168	    SetRole(op, role);
169	  }
170	
171	  void VisitStmt_(const BufferStoreNode *op) final {
172	    auto scope = StorageScope::Create(GetPtrStorageScope(op->buffer->data));
173	    bool is_shared_store = scope.rank == StorageRank::kShared;
174	    if (producer_buffers_.count(op->buffer.get())) {
175	      SetRole(op, Role::kBoth);
176	      return;
177	    }
178	    if (!is_shared_store) {
179	      SetRole(op, Role::kConsumer);
180	      return;
181	    }
182	
183	    // Check reads from global
184	    Block block(/*iter_vars=*/{}, /*reads=*/{}, /*writes=*/{}, /*name_hint=*/"",
185	                /*body*/ tvm::ffi::GetRef<Stmt>(op));
186	    auto access = GetBlockReadWriteRegion(block, buffer_data_to_buffer_);
187	    auto reads = access[0];
188	    Role role = Role::kProducer;
189	    if (reads.empty())
190	      role = Role::kConsumer;
191	    for (auto read : reads) {
192	      if (read->buffer.scope() != "global") {
193	        role = Role::kConsumer;
194	        break;
195	      }
196	    }
197	    if (role == Role::kProducer)
198	      has_simt_copy_ = true;
199	    SetRole(op, role);
200	  }
201	
202	  void VisitStmt_(const SeqStmtNode *op) final {
203	    StmtVisitor::VisitStmt_(op);
204	    auto role = GetRole(op->seq[0]);
205	    for (auto stmt : op->seq) {
206	      if (role != GetRole(stmt)) {
207	        role = Role::kBoth;
208	        break;
209	      }
210	    }
211	    SetRole(op, role);
212	  }
213	
214	  void VisitStmt_(const IfThenElseNode *op) final {
215	    StmtVisitor::VisitStmt_(op);
216	    auto role = GetRole(op->then_case);
217	    if (op->else_case.defined()) {
218	      auto role_else = GetRole(op->else_case.value());
219	      if (role != role_else)
220	        role = Role::kBoth;
221	    }
222	    SetRole(op, role);
223	  }
224	
225	  void VisitStmt_(const BlockRealizeNode *op) final {
226	    StmtVisitor::VisitStmt_(op);
227	    SetRole(op, GetRole(op->block));
228	  }
229	
230	  void VisitStmt_(const AllocateNode *op) final {
231	    StmtVisitor::VisitStmt_(op);
232	    Role role = Role::kConsumer;
233	    SetRole(op, role);
234	  }
235	
236	  template <class NodeType> void HandleBodyStmt(const NodeType *op) {
237	    StmtVisitor::VisitStmt_(op);
238	    SetRole(op, GetRole(op->body));
239	  }
240	
241	  void VisitStmt_(const ForNode *op) final { HandleBodyStmt(op); }
242	  void VisitStmt_(const WhileNode *op) final { HandleBodyStmt(op); }
243	  void VisitStmt_(const LetStmtNode *op) final { HandleBodyStmt(op); }
244	  void VisitStmt_(const AttrStmtNode *op) final { HandleBodyStmt(op); }
245	  void VisitStmt_(const AssertStmtNode *op) final { HandleBodyStmt(op); }
246	  void VisitStmt_(const BlockNode *op) final { HandleBodyStmt(op); }
247	
248	  bool HasProducer() { return has_simt_copy_ || has_bulk_copy_; }
249	
250	  bool HasSimtCopy() { return has_simt_copy_; }
251	
252	private:
253	  void SetRole(const StmtNode *stmt, Role role) { map_[stmt] = role; }
254	  Map<Var, Buffer> buffer_data_to_buffer_;
255	  std::unordered_map<const StmtNode *, Role> map_;
256	  bool has_simt_copy_ = false;
257	  bool has_bulk_copy_ = false;
258	  std::unordered_set<const BufferNode *> producer_buffers_;
259	};
