322	// Rewrite the producer Stmt to use the correct barrier index
323	class MbarrierRewriter : public StmtExprMutator {
324	public:
325	  static Stmt Rewrite(Stmt stmt, PrimExpr barrier_id) {
326	    MbarrierRewriter rewriter;
327	    rewriter.producer_barrier_idx_ = std::move(barrier_id);
328	    return rewriter(std::move(stmt));
329	  }
330	
331	private:
332	  PrimExpr VisitExpr_(const CallNode *op) final {
333	    auto call = Downcast<Call>(StmtExprMutator::VisitExpr_(op));
334	    if (call->op.same_as(tma_load()) || call->op.same_as(tma_load_im2col())) {
335	      auto mbar = makeGetBarrier(producer_barrier_idx_);
336	      auto arg0 = call->args[0].as<Call>();
337	      // Check if this is a 1D TMA load
338	      auto is_1d_tma_load =
339	          arg0 && !arg0.value()->op.same_as(create_tma_descriptor()) &&
340	          call->op.same_as(tma_load());
341	      if (is_1d_tma_load) {
342	        call.CopyOnWrite()->args.Set(2, mbar);
343	      } else {
344	        Call access_ptr = Downcast<Call>(call->args[2]);
345	        ICHECK(access_ptr->op.same_as(builtin::tvm_access_ptr()));
346	        call.CopyOnWrite()->args.Set(1, mbar);
347	      }
348	    }
349	    return call;
350	  }
351	  PrimExpr producer_barrier_idx_;
352	};
