354	class ThreadIdxRewriter : public StmtExprMutator {
355	public:
356	  static Stmt Rewrite(Stmt stmt, Var thread_var, PrimExpr replaced,
357	                      PrimExpr thread_extent, bool do_shuffle = false) {
358	    auto rewriter =
359	        ThreadIdxRewriter(std::move(thread_var), std::move(replaced),
360	                          std::move(thread_extent), do_shuffle);
361	    return rewriter(std::move(stmt));
362	  }
363	
364	private:
365	  ThreadIdxRewriter(Var thread_var, PrimExpr replaced, PrimExpr thread_extent,
366	                    bool do_shuffle)
367	      : thread_var_(std::move(thread_var)), replaced_(std::move(replaced)),
368	        thread_extent_(std::move(thread_extent)), do_shuffle_(do_shuffle) {}
369	
370	  PrimExpr VisitExpr_(const VarNode *var) final {
371	    if (var == thread_var_.get()) {
372	      return replaced_;
373	    } else {
374	      return StmtExprMutator::VisitExpr_(var);
375	    }
376	  }
377	
378	  Stmt VisitStmt_(const IfThenElseNode *op) final {
379	    auto f_uses_thread_index = [=](const tvm::tir::VarNode *parameter) {
380	      return parameter == thread_var_.get();
381	    };
382	    maybe_thread_opt_ = false;
383	    if (!op->else_case.defined() && op->condition.as<EQNode>() &&
384	        UsesVar(op->condition, f_uses_thread_index) &&
385	        !(UsesVar(op->then_case, f_uses_thread_index))) {
386	      auto eq_op = Downcast<EQ>(op->condition);
387	      if (eq_op->a.as<VarNode>() == thread_var_.get() ||
388	          eq_op->b.as<VarNode>() == thread_var_.get()) {
389	        maybe_thread_opt_ = true;
390	      }
391	      auto then_case = StmtExprMutator::VisitStmt(op->then_case);
392	      maybe_thread_opt_ = do_shuffle_ && maybe_thread_opt_ && has_tma_op_;
393	      has_tma_op_ = false;
394	      if (maybe_thread_opt_) {
395	        return IfThenElse(
396	            Call(DataType::Bool(), tl_shuffle_elect(), {thread_extent_}),
397	            StmtExprMutator::VisitStmt(op->then_case), std::nullopt);
398	      }
399	    }
400	    return StmtExprMutator::VisitStmt_(op);
401	  }
402	
403	  PrimExpr VisitExpr_(const CallNode *op) final {
404	    if (op->op.same_as(tl::tma_load()) ||
405	        op->op.same_as(tl::tma_load_im2col()) ||
406	        op->op.same_as(tl::tma_store())) {
407	      has_tma_op_ = true;
408	    }
409	    return StmtExprMutator::VisitExpr_(op);
410	  }
411	
412	  Var thread_var_;
413	  PrimExpr replaced_;
414	  PrimExpr thread_extent_;
415	  bool maybe_thread_opt_ = false;
416	  bool do_shuffle_;
417	  bool has_tma_op_ = false;
418	};
