429	struct OpInfo {
430	  int group_size{}, order{}, stage{};
431	  std::vector<int> group;
432	};
433	struct PipelineInfo {
434	  std::vector<OpInfo> op_infos;
435	
436	  PipelineInfo() = default;
437	  PipelineInfo(const Array<Array<Integer>> &group_info,
438	               const Array<Integer> &order_info,
439	               const Array<Integer> &stage_info) {
440	    int n = static_cast<int>(group_info.size());
441	    ICHECK(n == static_cast<int>(order_info.size()));
442	    ICHECK(n == static_cast<int>(stage_info.size()));
443	    // int cur_id = 0;
444	    for (int i = 0; i < n; i++) {
445	      OpInfo op_info;
446	      op_info.group_size = group_info[i].size();
447	      for (int j = 0; j < op_info.group_size; j++) {
448	        op_info.group.push_back(group_info[i][j].as<IntImmNode>()->value);
449	      }
450	      op_info.order = order_info[i].as<IntImmNode>()->value;
451	      op_info.stage = stage_info[i].as<IntImmNode>()->value;
452	      op_infos.push_back(op_info);
453	    }
454	  }
455	
456	  PipelineInfo(const PipelineInfo &other) {
457	    for (const auto &op_info : other.op_infos) {
458	      op_infos.push_back(op_info);
459	    }
460	  }
461	
462	  std::pair<int, int> FindStmt(int stmt_idx) {
463	    for (size_t i = 0; i < op_infos.size(); i++) {
464	      for (size_t j = 0; j < op_infos[i].group.size(); j++) {
465	        if (op_infos[i].group[j] == stmt_idx) {
466	          return std::make_pair(i, j);
467	        }
468	      }
469	    }
470	    return std::make_pair(-1, -1);
471	  }
472	
473	  void UpdateOrder(int order) {
474	    for (int i = 0; i < static_cast<int>(op_infos.size()); i++) {
475	      if (op_infos[i].order >= order && op_infos[i].order > 0) {
476	        op_infos[i].order++;
477	      }
478	    }
479	  }
480	
481	  int SplitOp(int stmt_idx) {
482	    auto pair = FindStmt(stmt_idx);
483	    int op_idx = pair.first;
484	    int inner_idx = pair.second;
485	    ICHECK(op_idx != -1);
486	    ICHECK(inner_idx != -1);
487	    OpInfo half0;
488	    OpInfo half1;
489	    // The order to do sync
490	    int sync_order = op_infos[op_idx].order + 1;
491	    UpdateOrder(sync_order);
492	
493	    half0.group_size = inner_idx + 1;
494	    half0.order = op_infos[op_idx].order;
495	    half0.stage = op_infos[op_idx].stage;
496	    for (int i = 0; i <= inner_idx; i++) {
497	      half0.group.push_back(op_infos[op_idx].group[i]);
498	    }
499	    half1.group_size = op_infos[op_idx].group_size - inner_idx - 1;
500	    half1.order = op_infos[op_idx].order + 2;
501	    half1.stage = op_infos[op_idx].stage;
502	    for (int i = inner_idx + 1; i < op_infos[op_idx].group_size; i++) {
503	      half1.group.push_back(op_infos[op_idx].group[i]);
504	    }
505	    op_infos.erase(op_infos.begin() + op_idx);
506	    if (half0.group_size > 0) {
507	      op_infos.insert(op_infos.begin() + op_idx, half0);
508	    }
509	    if (half1.group_size > 0) {
510	      UpdateOrder(half1.order);
511	      op_infos.insert(op_infos.begin() + op_idx + 1, half1);
512	    }
513	    return sync_order;
514	  }
515	
516	  void PrintPipelineInfo() {
517	    std::cout << "Print op_infos:" << '\n';
518	    for (size_t i = 0; i < op_infos.size(); i++) {
519	      std::cout << i << " " << op_infos[i].group_size << " "
520	                << op_infos[i].order << " " << op_infos[i].stage << '\n';
521	    }
522	    std::cout << "End of print" << '\n';
523	  }
524	};
