526	class GroupOpRewriter : public StmtExprMutator {
527	public:
528	  GroupOpRewriter(const PipelineInfo &pipeline_info)
529	      : pipeline_info_(pipeline_info) {}
530	
531	private:
532	  Stmt VisitStmt_(const ForNode *op) final {
533	    Map<String, ObjectRef> annotations;
534	    annotations.Set(String("stmt_group"), Integer(1));
535	    auto original_node = (op->body).as<SeqStmtNode>();
536	    if (!original_node) {
537	      return tvm::ffi::GetRef<For>(op);
538	    }
539	    Array<Stmt> new_body;
540	    int cur_id = 0;
541	    for (int i = 0; i < static_cast<int>(pipeline_info_.op_infos.size()); i++) {
542	      if (pipeline_info_.op_infos[i].group_size == 0)
543	        continue;
544	      Array<Stmt> block_stmt;
545	      for (int j = 0;
546	           j < static_cast<int>(pipeline_info_.op_infos[i].group_size); j++) {
547	        // ICHECK(group_info_[i][j].as<IntImmNode>());
548	        // int index =
549	        // static_cast<int>(group_info_[i][j].as<IntImmNode>()->value);
550	        ICHECK(original_node->seq[cur_id].as<BlockNode>());
551	        auto block = original_node->seq[cur_id].as<BlockNode>();
552	        // TODO: handle nested seqstmt
553	        block_stmt.push_back(block->body);
554	        cur_id++;
555	      }
556	      new_body.push_back(MakeGroupBlock(
557	          block_stmt.size() == 1 ? block_stmt[0]
558	                                 // NOLINTNEXTLINE(performance-move-const-arg)
559	                                 : SeqStmt(std::move(block_stmt)),
560	          annotations));
561	    }
562	    Array<Integer> order_anno;
563	    Array<Integer> stage_anno;
564	    for (const auto &op_info : pipeline_info_.op_infos) {
565	      order_anno.push_back(Integer(op_info.order));
566	      stage_anno.push_back(Integer(op_info.stage));
567	    }
568	    Map<String, Any> for_annotations = op->annotations;
569	    for_annotations.erase("tl_pipeline_group");
570	    for_annotations.Set("software_pipeline_order", order_anno);
571	    for_annotations.Set("software_pipeline_stage", stage_anno);
572	    For new_for =
573	        For(op->loop_var, op->min, op->extent, op->kind,
574	            new_body.size() == 1 ? new_body[0] : SeqStmt(std::move(new_body)),
575	            op->thread_binding, for_annotations);
576	    return new_for;
577	  }
578	
579	  PipelineInfo pipeline_info_;
580	};
