582	class WgMMACollector : public StmtExprVisitor {
583	public:
584	  WgMMACollector() = default;
585	
586	  void VisitExpr_(const CallNode *op) final {
587	    if (op->op.same_as(tl_gemm()) || op->op.same_as(tl_gemm_sp())) {
588	      auto op_name = std::string(op->args[0].as<StringImmNode>()->value);
589	      if (has_wgmma_) {
590	        has_wgmma_ =
591	            op_name.find("false") == std::string::npos && !in_if_scope_;
592	      }
593	    }
594	    StmtExprVisitor::VisitExpr_(op);
595	  }
596	
597	  void VisitStmt_(const IfThenElseNode *op) final {
598	    in_if_scope_ = true;
599	    StmtExprVisitor::VisitStmt(op->then_case);
600	    if (op->else_case.defined()) {
601	      StmtExprVisitor::VisitStmt(op->else_case.value());
602	    }
603	    in_if_scope_ = false;
604	  }
605	
606	  static bool HasWgMMA(const Stmt &stmt) {
607	    auto collector = WgMMACollector();
608	    collector(stmt);
609	    return collector.has_wgmma_;
610	  }
611	
612	  bool has_wgmma_{true};
613	  bool in_if_scope_{false};
