616	class WSCodeEmitter : public StmtMutator {
617	public:
618	  WSCodeEmitter(bool is_emitting_producer, const IterVar &thread_iv,
619	                Map<Var, Buffer> buffer_data_to_buffer,
620	                const WarpSpecializedRoleMarker &marker,
621	                bool mbarrier_only = false)
622	      : is_emitting_producer_(is_emitting_producer),
623	        buffer_data_to_buffer_(std::move(buffer_data_to_buffer)),
624	        marker_(marker), thread_var_(thread_iv->var),
625	        mbarrier_only_(mbarrier_only) {}
626	
627	  /**
628	   * @brief Whether a SIMT-style bulk copy was detected.
629	   *
630	   * Returns true when a simulated SIMT (thread-parallel) copy pattern was
631	   * observed during analysis/emission, which can affect barrier insertion and
632	   * copy emission.
633	   *
634	   * @return true if a SIMT copy was detected; false otherwise.
635	   */
636	  bool hasSimtCopy() const { return has_simt_copy_; }
637	
638	private:
639	  template <
640	      typename NodeType> /**
641	                          * @brief Filter a statement by its producer/consumer
642	                          * role for emission.
643	                          *
644	                          * Returns one of:
645	                          * - the original statement (unchanged) when this
646	                          * emitter should emit it,
647	                          * - the result of visiting the statement (to descend
648	                          * into it) when mbarrier-only mode requires full
649	                          * traversal for non-producer roles,
650	                          * - an empty evaluate (`Evaluate(0)`) when the
651	                          * statement should be omitted.
652	                          *
653	                          * The decision is based on the role of `op` as
654	                          * reported by `marker_`, the emitter mode
655	                          * (`is_emitting_producer_`), and the `mbarrier_only_`
656	                          * flag.
657	                          *
658	                          * @param op The statement node to filter; its role is
659	                          * queried via `marker_`.
660	                          * @return Stmt The statement to place into the emitted
661	                          * IR (possibly transformed or an empty evaluate).
662	                          */
663	  Stmt FilterByRole(const NodeType *op) {
664	    Role role = marker_.GetRole(op);
665	    if (mbarrier_only_) {
666	      if (role != Role::kProducer)
667	        return StmtMutator::VisitStmt_(op);
668	    }
669	    if (role == Role::kBoth) {
670	      return StmtMutator::VisitStmt_(op);
671	    } else if ((role == Role::kProducer) == is_emitting_producer_) {
672	      return tvm::ffi::GetRef<Stmt>(op);
673	    } else {
674	      return Evaluate(0);
675	    }
676	  }
677	
678	  Stmt VisitStmt_(const SeqStmtNode *op) final {
679	
680	    bool has_producer = false;
681	    for (auto stmt : op->seq) {
682	      if (marker_.GetRole(stmt) == Role::kProducer) {
683	        has_producer = true;
684	        break;
685	      }
686	    }
687	    bool need_producer_sync =
688	        has_producer && marker_.GetRole(op) == Role::kBoth;
689	    if (!need_producer_sync)
690	      return FilterByRole(op);
691	
692	    auto seq_transformed =
693	        op->seq.Map([&](const Stmt &stmt) { return VisitStmt(stmt); });
694	
695	    auto map = ExtractSyncPattern(op->seq);
696	
697	    /*
698	      std::cout << "Print ExtractSyncPattern" << std::endl;
699	      for (int i = 0; i < static_cast<int>(op->seq.size()); i++) {
700	        std::cout << i << " " << map.acquire[i] << " " << map.release[i] << " "
701	        << map.release_after[i] << std::endl;
702	      }
703	      std::cout << "Print sync pattern" << std::endl;
704	      for (auto pattern : map.patterns) {
705	        std::cout << pattern.release_idx << " " << pattern.acquire_idx <<
706	        std::endl;
707	      }
708	      std::cout << "End of ExtractSyncPattern" << std::endl;
709	      pipeline_info_.PrintPipelineInfo();
710	    */
711	    Array<Stmt> new_body;
712	    Map<String, ObjectRef> annotations;
713	    annotations.Set(String("stmt_group"), Integer(1));
714	
715	    if (is_emitting_producer_) { // producer case
716	      ProducerTraitsCollector collector;
717	      for (int i = 0; i < static_cast<int>(op->seq.size()); i++) {
718	        Array<Stmt> block_stmt = {};
719	        if (!mbarrier_only_) {
720	          if (marker_.GetRole(op->seq[i]) == Role::kConsumer)
721	            continue;
722	          if (marker_.GetRole(op->seq[i]) == Role::kBoth) {
723	            block_stmt.push_back(seq_transformed[i]);
724	            new_body.push_back(
725	                MakeGroupBlock(block_stmt.size() == 1
726	                                   ? block_stmt[0]
727	                                   // NOLINTNEXTLINE(performance-move-const-arg)
728	                                   : SeqStmt(std::move(block_stmt)),
729	                               annotations));
730	            continue;
731	          }
732	        }
733	
734	        for (int pattern_idx : map.acquire[i]) {
735	          PrimExpr acquire_barrier_id =
736	              stage_ + num_barriers_ + num_stages_ * pattern_idx;
737	          PrimExpr parity = map.is_loop_dependency(pattern_idx)
738	                                ? bitwise_xor(parity_, 1)
739	                                : parity_;
740	          block_stmt.push_back(makeParityWait(acquire_barrier_id, parity));
741	        }
742	        ICHECK(!map.release[i].empty());
743	        for (size_t j = 0; j < map.release[i].size(); j++) {
744	          int pattern_idx = map.release[i][j];
745	          PrimExpr release_barrier_id =
746	              stage_ + num_barriers_ + num_stages_ * pattern_idx;
747	          auto stmt =
748	              MbarrierRewriter::Rewrite(seq_transformed[i], release_barrier_id);
749	          collector.Collect(stmt);
750	          block_stmt.push_back(stmt);
751	          if (collector.HasSimtCopy()) {
752	            block_stmt.push_back(makeCpAsyncBarrier(release_barrier_id));
753	            has_simt_copy_ = true;
754	          }
755	          if (map.release_after[i][j]) {
756	            block_stmt.push_back(makeArriveBarrier(release_barrier_id));
757	            for (int s = 0; s < num_stages_; s++) {
758	              released_barrier_.insert(s + num_barriers_ +
759	                                       num_stages_ * pattern_idx);
760	            }
761	          }
762	          collector.Clear();
763	          new_body.push_back(
764	              MakeGroupBlock(block_stmt.size() == 1
765	                                 ? block_stmt[0]
766	                                 // NOLINTNEXTLINE(performance-move-const-arg)
767	                                 : SeqStmt(std::move(block_stmt)),
768	                             annotations));
769	        }
770	      }
771	    } else { // consumer case
772	      for (int i = 0; i < static_cast<int>(op->seq.size()); i++) {
773	        Array<Stmt> block_stmt = {};
774	        if (marker_.GetRole(op->seq[i]) == Role::kProducer)
775	          continue;
776	        for (int pattern_idx : map.acquire[i]) {
777	          PrimExpr acquire_barrier_id =
778	              stage_ + num_barriers_ + num_stages_ * pattern_idx;
779	          PrimExpr parity = map.is_loop_dependency(pattern_idx)
780	                                ? bitwise_xor(parity_, 1)
781	                                : parity_;
782	          block_stmt.push_back(makeParityWait(acquire_barrier_id, parity));
783	        }
784	        block_stmt.push_back(seq_transformed[i]);
785	        for (size_t j = 0; j < map.release[i].size(); j++) {
786	          if (map.release_after[i][j]) {
787	            int pattern_idx = map.release[i][j];
788	            PrimExpr release_barrier_id =
789	                stage_ + num_barriers_ + num_stages_ * pattern_idx;
790	            block_stmt.push_back(makeArriveBarrier(release_barrier_id));
791	            for (int s = 0; s < num_stages_; s++) {
792	              released_barrier_.insert(s + num_barriers_ +
793	                                       num_stages_ * pattern_idx);
794	            }
795	          }
796	        }
797	        new_body.push_back(MakeGroupBlock(
798	            block_stmt.size() == 1 ? block_stmt[0]
799	                                   // NOLINTNEXTLINE(performance-move-const-arg)
800	                                   : SeqStmt(std::move(block_stmt)),
801	            annotations));
802	      }
803	      // Filter out the producer stmts
804	      int cur_id = 0;
805	      PipelineInfo new_pipeline_info;
806	      for (int i = 0; i < static_cast<int>(pipeline_info_.op_infos.size());
807	           i++) {
808	        auto op_info = pipeline_info_.op_infos[i];
809	        bool is_producer = false;
810	        for (int j = 0; j < op_info.group_size; j++) {
811	          if (marker_.GetRole(op->seq[cur_id]) == Role::kProducer) {
812	            is_producer = true;
813	          }
814	          cur_id++;
815	        }
816	        if (is_producer) {
817	          ICHECK(op_info.group_size == 1);
818	        } else {
819	          new_pipeline_info.op_infos.push_back(op_info);
820	        }
821	      }
822	      pipeline_info_ = new_pipeline_info;
823	    }
824	
825	    num_barriers_ += map.patterns.size() * num_stages_;
826	
827	    ICHECK(!new_body.empty());
828	    return new_body.size() == 1 ? new_body[0] : SeqStmt(std::move(new_body));
829	  }
830	
831	  Stmt VisitStmt_(const ForNode *op) final {
832	    int num_stages = 1;
833	    auto num_stages_anno = op->annotations.Get("num_stages");
834	    if (num_stages_anno) {
835	      ICHECK(num_stages_anno->as<IntImmNode>());
836	      num_stages = static_cast<int>(num_stages_anno->as<IntImmNode>()->value);
837	      ICHECK(num_stages_ == 1) << "Nested pipeline not supported.";
838	    }
839	    loop_stack_.emplace_back(LoopInfo{op->loop_var, op->extent, op->min});
840	
841	    Array<Array<Integer>> group_info_array;
842	    Array<Integer> order_info_array;
843	    Array<Integer> stage_info_array;
844	
845	    auto group_anno = op->annotations.Get("tl_pipeline_group");
846	    if (group_anno) {
847	      group_info_array = Downcast<Array<Array<Integer>>>(group_anno.value());
848	    }
849	    auto order_anno = op->annotations.Get("tl_pipeline_order");
850	    if (order_anno) {
851	      order_info_array = Downcast<Array<Integer>>(order_anno.value());
852	    }
853	    auto stage_anno = op->annotations.Get("tl_pipeline_stage");
854	    if (stage_anno) {
855	      stage_info_array = Downcast<Array<Integer>>(stage_anno.value());
856	    }
857	
858	    PipelineInfo pipeline_info(group_info_array, order_info_array,
859	                               stage_info_array);
860	    if (!pipeline_info.op_infos.empty()) {
861	      ICHECK(pipeline_info_.op_infos.empty())
862	          << "Nested pipeline not supported.";
863	    }
864	
865	    PrimExpr parity_before = std::move(parity_);
866	    PrimExpr stage_before = std::move(stage_);
867	    int num_stages_before = num_stages_;
868	    PipelineInfo pipeline_info_before = pipeline_info_;
869	
870	    num_stages_ = num_stages;
871	    pipeline_info_ = pipeline_info;
872	    PrimExpr linear_index = loop_stack_[0].loop_var - loop_stack_[0].min;
873	    for (size_t i = 1; i < loop_stack_.size(); ++i) {
874	      linear_index = linear_index * loop_stack_[i].extent +
875	                     (loop_stack_[i].loop_var - loop_stack_[i].min);
876	    }
877	    stage_ = FloorMod(linear_index, num_stages);
878	    parity_ = FloorMod(
879	        parity_before * op->extent + FloorDiv(linear_index, num_stages), 2);
880	    auto result = FilterByRole(op);
881	
882	    Stmt grouped_for_node;
883	    if (result.as<ForNode>() && group_anno && !group_info_array.empty() &&
884	        !is_emitting_producer_) {
885	      GroupOpRewriter group_op_rewriter(pipeline_info_);
886	      auto for_node = Downcast<For>(result);
887	      grouped_for_node = group_op_rewriter(for_node);
888	    }
889	
890	    parity_ = std::move(parity_before);
891	    stage_ = std::move(stage_before);
892	    num_stages_ = num_stages_before;
893	    pipeline_info_ = pipeline_info_before;
894	
895	    // remove pipeline annotation
896	    auto for_node = result.as<For>();
897	    if (result.as<ForNode>()) {
898	      auto for_node = Downcast<For>(result);
899	      for_node.CopyOnWrite()->annotations.erase("num_stages");
900	      if (is_emitting_producer_ || group_info_array.empty()) {
901	        for_node.CopyOnWrite()->annotations.erase("tl_pipeline_order");
902	        for_node.CopyOnWrite()->annotations.erase("tl_pipeline_stage");
903	      }
904	      if (is_emitting_producer_ || !group_anno || group_info_array.empty()) {
905	        loop_stack_.pop_back();
906	        return for_node;
907	      }
908	      loop_stack_.pop_back();
909	      return grouped_for_node;
910	    }
911	    loop_stack_.pop_back();
912	    return result;
913	  }
