924	  struct SyncPattern {
925	    int release_idx, acquire_idx;
926	  };
927	
928	  struct SyncPatternMap {
929	    std::vector<std::vector<int>> acquire;
930	    std::vector<std::vector<int>> release;
931	    std::vector<std::vector<bool>> release_after;
932	    std::vector<SyncPattern> patterns;
933	
934	    void resize(size_t n) {
935	      acquire.resize(n);
936	      release.resize(n);
937	      release_after.resize(n);
938	    }
939	
940	    bool is_loop_dependency(int pattern_idx) {
941	      return patterns[pattern_idx].release_idx >
942	             patterns[pattern_idx].acquire_idx;
943	    }
944	  };
945	
946	  std::vector<SyncPattern>
947	  CreateBaseSyncPairs(const Array<Stmt> &seq_stmt,
948	                      const std::vector<bool> &is_producer) {
949	    const int n = seq_stmt.size();
950	    std::vector<std::set<const BufferNode *>> reads, writes;
951	    reads.reserve(n);
952	    writes.reserve(n);
953	    for (int i = 0; i < n; i++) {
954	      Block block(/*iter_vars=*/{}, /*reads=*/{}, /*writes=*/{},
955	                  /*name_hint=*/"",
956	                  /*body*/ seq_stmt[i]);
957	      auto access = GetBlockAccessRegion(block, buffer_data_to_buffer_);
958	      std::set<const BufferNode *> read_set, write_set;
959	      for (auto region : access[0]) {
960	        auto var = region->buffer->data;
961	        if (buffer_data_to_buffer_.count(var)) {
962	          read_set.insert(buffer_data_to_buffer_[var].get());
963	        } else {
964	          read_set.insert(region->buffer.get());
965	        }
966	      }
967	      for (auto region : access[1]) {
968	        auto var = region->buffer->data;
969	        if (buffer_data_to_buffer_.count(var)) {
970	          write_set.insert(buffer_data_to_buffer_[var].get());
971	        } else {
972	          write_set.insert(region->buffer.get());
973	        }
974	      }
975	      reads.push_back(std::move(read_set));
976	      writes.push_back(std::move(write_set));
977	    }
978	
979	    auto intersect_fn = [](const std::set<const BufferNode *> &lhs,
980	                           const std::set<const BufferNode *> &rhs) {
981	      for (auto ptr : lhs)
982	        if (rhs.count(ptr))
983	          return true;
984	      return false;
985	    };
986	
987	    std::vector<SyncPattern> sync_patterns;
988	    // producer_release consumer_acquire,
989	    // inject before the first consumer stmt for each producer
990	    for (int i = 0; i < n; i++) {
991	      for (int j = i + 1; j < n; j++) {
992	        if (is_producer[i] != is_producer[j] &&
993	            (intersect_fn(writes[i], reads[j]) ||
994	             intersect_fn(reads[i], writes[j]))) {
995	          sync_patterns.push_back({i, j});
996	          break;
997	        }
998	      }
999	    }
1000	
1001	    // consumer_release producer_acquire
1002	    // valid when is_loop is true
1003	    // inject before the earliest producer stmt for each consumer
1004	    bool in_loop = !is_zero(parity_);
1005	    if (in_loop) {
1006	      for (int i = 0; i < n; i++) {
1007	        for (int j = 0; j < i; j++) {
1008	          if (is_producer[i] != is_producer[j] &&
1009	              (intersect_fn(writes[i], reads[j]) ||
1010	               intersect_fn(reads[i], writes[j]))) {
1011	            sync_patterns.push_back({i, j});
1012	            break;
1013	          }
1014	        }
1015	      }
1016	    }
1017	
1018	    return sync_patterns;
1019	  }
1020	
1021	  static std::vector<SyncPattern>
1022	  RemoveUnusedSyncPatterns(const std::vector<SyncPattern> &sync_patterns,
1023	                           const std::vector<bool> &is_producer) {
1024	    /*
1025	      Simplify multiple release-acquire pairs into one
1026	      ------------------
1027	        Produce(A)
1028	        Produce(B)
1029	        Consume(A, B)
1030	      ------------------
1031	      [(0, 2), (1, 2), (2, 0)] -> [(1, 2), (2, 0)]
1032	
1033	      Or
1034	      ------------------
1035	        Produce(A, B)
1036	        Consume(A)
1037	        Consume(B)
1038	      ------------------
1039	      [(0, 1), (1, 0), (2, 0)] -> [(0, 1), (2, 0)]
1040	    */
1041	    int M = sync_patterns.size();
1042	    std::vector<bool> removed(M, false);
1043	    for (int i = 0; i < M; i++) {
1044	      for (int j = 0; j < M; j++) {
1045	        if (is_producer[sync_patterns[i].acquire_idx] ==
1046	                is_producer[sync_patterns[j].acquire_idx] &&
1047	            sync_patterns[i].acquire_idx >= sync_patterns[j].acquire_idx &&
1048	            sync_patterns[i].release_idx < sync_patterns[j].release_idx)
1049	          removed[i] = true;
1050	      }
1051	    }
1052	
1053	    std::vector<SyncPattern> sync_pattern_cleaned;
1054	    sync_pattern_cleaned.reserve(M);
1055	    for (int i = 0; i < M; i++)
1056	      if (!removed[i])
1057	        sync_pattern_cleaned.push_back(sync_patterns[i]);
1058	
1059	    return sync_pattern_cleaned;
1060	  }
1061	
1062	  SyncPatternMap ExtractSyncPattern(const Array<Stmt> &seq_stmt) {
1063	    size_t num_stmts = seq_stmt.size();
1064	    std::vector<bool> is_producer;
1065	    is_producer.reserve(num_stmts);
1066	    for (auto stmt : seq_stmt) {
1067	      is_producer.push_back(marker_.GetRole(stmt) == Role::kProducer);
1068	    }
1069	
1070	    auto sync_patterns_base = CreateBaseSyncPairs(seq_stmt, is_producer);
1071	    auto sync_patterns =
1072	        RemoveUnusedSyncPatterns(sync_patterns_base, is_producer);
1073	
1074	    // for (auto pattern : sync_patterns) {
1075	    //   std::cout << pattern.release_idx << " " << pattern.acquire_idx <<
1076	    //   std::endl;
1077	    // }
1078	
1079	    SyncPatternMap map;
1080	    map.resize(num_stmts);
1081	    map.patterns = sync_patterns;
1082	
1083	    for (size_t i = 0; i < sync_patterns.size(); i++) {
1084	      int acquire_idx = sync_patterns[i].acquire_idx;
1085	      int release_idx = sync_patterns[i].release_idx;
1086	
1087	      map.acquire[acquire_idx].push_back(i);
1088	      map.release[release_idx].push_back(i);
1089	      map.release_after[release_idx].push_back(true);
1090	    }
1091	
1092	    std::vector<int> cur_consumer_barrier, cur_producer_barrier;
1093	    for (int i = num_stmts - 1; i >= 0; i--) {
1094	      if (is_producer[i]) {
1095	        if (map.release[i].empty()) {
1096	          for (auto pattern_idx : cur_producer_barrier) {
1097	            map.release[i].push_back(pattern_idx);
1098	            map.release_after[i].push_back(false);
1099	          }
1100	        } else {
1101	          for (auto pattern_idx : map.release[i]) {
1102	            cur_producer_barrier.push_back(pattern_idx);
1103	          }
1104	        }
1105	      } else {
1106	        if (map.release[i].empty()) {
1107	          for (auto pattern_idx : cur_consumer_barrier) {
1108	            map.release[i].push_back(pattern_idx);
1109	            map.release_after[i].push_back(false);
1110	          }
1111	        } else {
1112	          for (auto pattern_idx : map.release[i]) {
1113	            cur_consumer_barrier.push_back(pattern_idx);
1114	          }
1115	        }
1116	      }
1117	    }
1118	    return map;
1119	  }
