1122	  Map<Var, Buffer> buffer_data_to_buffer_;
1123	  std::unordered_set<int> released_barrier_;
1124	  const WarpSpecializedRoleMarker &marker_;
1125	
1126	  int num_barriers_ = 0;
1127	  PrimExpr parity_ = 0;
1128	  PrimExpr stage_ = 0;
1129	  int num_stages_ = 1;
1130	  std::vector<LoopInfo> loop_stack_;
1131	  Var thread_var_;
1132	  bool mbarrier_only_ = false;
1133	  PipelineInfo pipeline_info_;
1134	  friend class WarpSpecializedRewriter;
1135	  bool has_simt_copy_ = false;
1136	};
1137	
1138	class WarpSpecializedRewriter : public StmtExprMutator {
1139	public:
1140	  WarpSpecializedRewriter(bool disable_warp_specialized,
1141	                          bool disable_shuffle_elect)
1142	      : disable_warp_specialized_(disable_warp_specialized),
1143	        disable_shuffle_elect_(disable_shuffle_elect) {}
1144	  static PrimFunc Substitute(PrimFunc f, bool disable_warp_specialized,
1145	                             bool disable_shuffle_elect) {
1146	    // Check if function only uses threadIdx.x before proceeding
1147	    if (!ThreadTagChecker::HasOnlyThreadIdxX(f)) {
1148	      LOG(WARNING) << "WarpSpecialize will be disabled because the program "
1149	                      "uses thread tags other than threadIdx.x."
1150	                   << "If you want to use warp specialization, please refactor "
1151	                      "your program to use threadIdx.x only";
1152	      // Return original function unchanged if other thread tags are found
1153	      return f;
1154	    }
1155	
1156	    auto T = WarpSpecializedRewriter(disable_warp_specialized,
1157	                                     disable_shuffle_elect);
1158	    T.buffer_lca_ = DetectBufferAccessLCA(f);
1159	    for (auto [buffer, _] : T.buffer_lca_)
1160	      T.buffer_data_to_buffer_.Set(buffer->data, buffer);
1161	    f.CopyOnWrite()->body = T(f->body);
1162	    return f;
1163	  }
1164	
1165	private:
1166	  Stmt VisitStmt_(const AttrStmtNode *op) final {
1167	    if (op->attr_key == tir::attr::thread_extent &&
1168	        Downcast<IterVar>(op->node)->thread_tag == "threadIdx.x") {
1169	      thread_iv_ = Downcast<IterVar>(op->node);
1170	      need_update_thread_extent_ = false;
1171	      AttrStmt attr_stmt = Downcast<AttrStmt>(StmtExprMutator::VisitStmt_(op));
1172	      if (need_update_thread_extent_) {
1173	        thread_iv_.CopyOnWrite()->dom = {0, updated_thread_extent_.value()};
1174	        attr_stmt.CopyOnWrite()->node = thread_iv_;
1175	        attr_stmt.CopyOnWrite()->value = updated_thread_extent_.value();
1176	      }
1177	      thread_iv_ = {};
1178	      return attr_stmt;
1179	    } else {
1180	      return StmtExprMutator::VisitStmt_(op);
1181	    }
1182	  }
1183	
1184	  // If users define a thread binding, we will replace the thread binding with
1185	  // threadIdx.x We require the thread binding is threadIdx.x, and the extent is
1186	  // the same as the thread extent
1187	  Stmt VisitStmt_(const ForNode *op) final {
1188	    ICHECK(thread_iv_.defined());
1189	    For for_node = Downcast<For>(StmtExprMutator::VisitStmt_(op));
1190	    if (for_node->kind == ForKind::kThreadBinding) {
1191	      ICHECK(for_node->thread_binding.defined());
1192	      String thread_tag = for_node->thread_binding.value()->thread_tag;
1193	      ICHECK(thread_tag == "threadIdx.x") << "Only support threadIdx.x";
1194	      Var thread_iv = Downcast<Var>(for_node->loop_var);
1195	      Stmt new_body =
1196	          ThreadIdxRewriter::Rewrite(for_node->body, thread_iv, thread_iv_, 0);
1197	      return new_body;
1198	    }
1199	    return for_node;
1200	  }
1201	
1202	  Stmt VisitStmt_(const BlockRealizeNode *op) final {
1203	    BlockRealize block_realize =
1204	        Downcast<BlockRealize>(StmtExprMutator::VisitStmt_(op));
1205	    if (!thread_iv_.defined()) {
1206	      return block_realize;
1207	    }
1208	
1209	    Block block = block_realize->block;
1210	    WarpSpecializedRoleMarker marker(buffer_data_to_buffer_);
1211	    marker.Prepare(block);
1212	    marker(block);
1213	    if (!marker.HasProducer()) {
1214	      // Cannot detect any producer here, directly return.
1215	      return block_realize;
1216	    }
1217	
1218	    if (disable_warp_specialized_) {
1219	      WSCodeEmitter mbarrier_emitter(true, thread_iv_, buffer_data_to_buffer_,
1220	                                     marker, true);
1221	      auto code = mbarrier_emitter(block->body);
1222	      int num_barriers = mbarrier_emitter.num_barriers_;
1223	      Array<PrimExpr> barrier_num_threads;
1224	      barrier_num_threads.reserve(num_barriers);
1225	      PrimExpr arrive_thread_count = thread_iv_->dom->extent;
1226	      for (int i = 0; i < num_barriers; i++) {
1227	        barrier_num_threads.push_back(arrive_thread_count);
1228	      }
1229	      Stmt init_barrier = Evaluate(Call(
1230	          DataType::Handle(), create_list_of_mbarrier(), barrier_num_threads));
1231	      block.CopyOnWrite()->body = SeqStmt({init_barrier, code});
1232	      block_realize.CopyOnWrite()->block = block;
1233	      return block_realize;
1234	    }
1235	    WSCodeEmitter producer(true, thread_iv_, buffer_data_to_buffer_, marker);
1236	    WSCodeEmitter consumer(false, thread_iv_, buffer_data_to_buffer_, marker,
1237	                           false);
1238	    Stmt producer_code = producer(block->body);
1239	    Stmt consumer_code = consumer(block->body);
1240	    PrimExpr consumer_thread_extent = thread_iv_->dom->extent;
1241	    PrimExpr producer_thread_extent = thread_iv_->dom->extent;
1242	    // Need one warp-group for bulk-copy only case
1243	    if (!marker.HasSimtCopy())
1244	      producer_thread_extent = 128;
1245	
1246	    updated_thread_extent_ = consumer_thread_extent + producer_thread_extent;
1247	
1248	    producer_code = ThreadIdxRewriter::Rewrite(
1249	        producer_code, thread_iv_->var,
1250	        thread_iv_->var - consumer_thread_extent, producer_thread_extent,
1251	        !disable_shuffle_elect_);
1252	    consumer_code = ThreadIdxRewriter::Rewrite(
1253	        consumer_code, thread_iv_->var, thread_iv_->var, consumer_thread_extent,
1254	        !disable_shuffle_elect_);
1255	    need_update_thread_extent_ = true;
1256	
1257	    ICHECK(producer.num_barriers_ == consumer.num_barriers_)
1258	        << producer.num_barriers_ << " " << consumer.num_barriers_;
1259	    int num_barriers = consumer.num_barriers_;
1260	    Array<PrimExpr> barrier_num_threads;
1261	    barrier_num_threads.reserve(num_barriers);
1262	    for (int i = 0; i < num_barriers; i++) {
1263	      PrimExpr arrive_thread_count =
1264	          producer.released_barrier_.count(i)
1265	              ? (producer.hasSimtCopy() ? producer_thread_extent : 1)
1266	              : consumer_thread_extent;
1267	      barrier_num_threads.push_back(arrive_thread_count);
1268	    }
1269	
1270	    Stmt init_barrier = Evaluate(Call(
1271	        DataType::Handle(), create_list_of_mbarrier(), barrier_num_threads));
1272	    Stmt body = IfThenElse(GE(thread_iv_->var, consumer_thread_extent),
1273	                           producer_code, consumer_code);
1274	    // Add an attr here to handle the partial thread count in ThreadSync pass.
1275	    Array<IntImm> ws_partition = {Downcast<IntImm>(producer_thread_extent),
1276	                                  Downcast<IntImm>(consumer_thread_extent)};
1277	    body = AttrStmt(ws_partition, attr::kWarpSpecializationScope, 0, body);
1278	
1279	    block.CopyOnWrite()->body = SeqStmt({init_barrier, body});
1280	    block_realize.CopyOnWrite()->block = block;
1281	    return block_realize;
1282	  }
1283	
1284	  WarpSpecializedRewriter() = default;
1285	
1286	  Map<Var, Buffer> buffer_data_to_buffer_;
1287	  Map<Buffer, Optional<Stmt>> buffer_lca_;
1288	  Map<Buffer, Buffer> buffer_remap_;
1289	  IterVar thread_iv_;
1290	  Optional<PrimExpr> updated_thread_extent_;
1291	  bool need_update_thread_extent_ = false;
1292	  bool disable_warp_specialized_ = false;
1293	  bool disable_shuffle_elect_ = false;
1294	};
1295	
1296	using namespace tir::transform;
1297	
1298	tvm::transform::Pass WarpSpecialized() {
1299	  auto pass_func = [=](PrimFunc f, const IRModule &m, PassContext ctx) {
1300	    bool disable_warp_specialized =
1301	        ctx->GetConfig<Bool>(kDisableWarpSpecialized, Bool(false)).value();
1302	    bool disable_shuffle_elect =
1303	        ctx->GetConfig<Bool>(kDisableShuffleElect, Bool(false)).value();
1304	    bool warp_specialized = WarpSpecializedDetector::Detect(f->body);
1305	
1306	    if (!warp_specialized) {
1307	      return WarpSpecializedRewriter::Substitute(f, disable_warp_specialized,
1308	                                                 disable_shuffle_elect);
1309	    } else {
1310	      auto node = ffi::String("default");
1311	      f.CopyOnWrite()->body =
1312	          AttrStmt(node, attr::kCustomWarpSpecialization, 1, f->body);
1313	      return f;
1314	    }
1315	  };
1316	  return CreatePrimFuncPass(pass_func, 0, "tl.WarpSpecialized", {});
1317	}
1318	
1319	TVM_FFI_STATIC_INIT_BLOCK() {
1320	  namespace refl = tvm::ffi::reflection;
1321	  refl::GlobalDef().def("tl.transform.WarpSpecialized", WarpSpecialized);
1322	}
1323	
1324	} // namespace tl
1325	} // namespace tvm
