22	bool isGemm(const Stmt &stmt) {
23	  bool is_gemm = false;
24	  if (stmt.as<EvaluateNode>()) {
25	    auto call = Downcast<Evaluate>(stmt)->value.as<CallNode>();
26	    if (call && call->op.same_as(Op::Get("tir.call_extern"))) {
27	      if (call->args[0].as<StringImmNode>()) {
28	        std::string name = Downcast<StringImm>(call->args[0])->value;
29	        if (name.find("gemm") != std::string::npos) {
30	          is_gemm = true;
31	        }
32	      }
33	    }
34	  }
35	  return is_gemm;
36	}
