38	bool isGemmSync(const Stmt &stmt) {
39	  bool is_gemm_sync = false;
40	  if (stmt.as<EvaluateNode>()) {
41	    auto call = Downcast<Evaluate>(stmt)->value.as<CallNode>();
42	    if (call && call->op.same_as(Op::Get("tir.call_extern"))) {
43	      if (call->args[0].as<StringImmNode>()) {
44	        std::string name = Downcast<StringImm>(call->args[0])->value;
45	        if (name.find("warpgroup_wait") != std::string::npos) {
46	          is_gemm_sync = true;
47	        }
48	      }
49	    }
50	  }
51	  return is_gemm_sync;
52	}
53	
54	bool isArriveBarrier(const Stmt &stmt) {
55	  bool is_arrive_barrier = false;
56	  if (stmt.as<EvaluateNode>()) {
57	    auto call = Downcast<Evaluate>(stmt)->value.as<CallNode>();
58	    if (call && call->op.same_as(Op::Get("tir.ptx_arrive_barrier"))) {
59	      is_arrive_barrier = true;
60	    }
61	  }
62	  return is_arrive_barrier;
63	}
64	
65	class WgmmaSyncRewriter : public StmtExprMutator {
66	public:
67	  static PrimFunc Substitute(PrimFunc f) {
68	    auto T = WgmmaSyncRewriter();
69	    T.buffer_lca_ = DetectBufferAccessLCA(f);
70	    for (auto [buffer, _] : T.buffer_lca_)
71	      T.buffer_data_to_buffer_.Set(buffer->data, buffer);
72	    f.CopyOnWrite()->body = T(f->body);
73	    return f;
74	  }
75	
76	private:
77	  void CollectWgmmaInfo(const SeqStmtNode *op) {
78	    for (int i = 0; i < static_cast<int>(op->seq.size()); i++) {
79	      auto stmt = op->seq[i];
80	      if (isGemm(stmt)) {
81	        gemm_stmts_.push_back(stmt);
82	        gemm_stmt_ids_.push_back(i);
83	        bool found_release = false;
84	        for (int j = i + 1; j < static_cast<int>(op->seq.size()); j++) {
85	          auto release_stmt = op->seq[j];
86	          if (isArriveBarrier(release_stmt)) {
87	            found_release = true;
88	            gemm_release_stmts_.push_back(release_stmt);
89	            break;
90	          }
91	        }
92	        if (!found_release) {
93	          gemm_release_stmts_.push_back(Evaluate(0));
94	        }
95	        // ICHECK(op->seq.size() > i + 1);
96	        // auto release_stmt = op->seq[i + 1];
97	        // auto next_call =
98	        // Downcast<Evaluate>(release_stmt)->value.as<CallNode>();
99	        // ICHECK(next_call);
100	        // ICHECK(next_call->op.same_as(Op::Get("tir.ptx_arrive_barrier")));
101	        Block block(/*iter_vars=*/{}, /*reads=*/{}, /*writes=*/{},
102	                    /*name_hint=*/"",
103	                    /*body*/ op->seq[i]);
104	        auto access = GetBlockReadWriteRegion(block, buffer_data_to_buffer_);
105	        std::set<const BufferNode *> read_set, write_set;
106	        for (auto region : access[0])
107	          read_set.insert(region->buffer.get());
108	        for (auto region : access[1])
109	          write_set.insert(region->buffer.get());
110	        gemm_read_buffers_.push_back(read_set);
111	        gemm_write_buffers_.push_back(write_set);
112	      }
113	    }
114	  }
115	
116	  Stmt VisitStmt_(const ForNode *op) final {
117	    auto order_anno = op->annotations.Get("tl_pipeline_order");
118	    if (!order_anno) {
119	      return StmtExprMutator::VisitStmt_(op);
120	    }
121	
122	    CollectWgmmaInfo(op->body.as<SeqStmtNode>());
123	    auto stmt_node = (op->body).as<SeqStmtNode>();
124	    ICHECK(stmt_node);
125	
126	    auto intersect_fn = [](const std::set<const BufferNode *> &lhs,
127	                           const std::set<const BufferNode *> &rhs) {
128	      for (auto ptr : lhs)
129	        if (rhs.count(ptr))
130	          return true;
131	      return false;
132	    };
133	
134	    for (int r = 0; r < static_cast<int>(gemm_stmts_.size()); r++) {
135	      bool found = false;
136	      auto last_stmt = Stmt();
137	      for (int i = 0; i < static_cast<int>(stmt_node->seq.size()); i++) {
138	        if (stmt_node->seq[i].same_as(gemm_stmts_[r])) {
139	          found = true;
140	          last_stmt = stmt_node->seq[i];
141	          continue;
142	        }
143	        if (!found)
144	          continue;
145	        Block block(/*iter_vars=*/{}, /*reads=*/{}, /*writes=*/{},
146	                    /*name_hint=*/"",
147	                    /*body*/ stmt_node->seq[i]);
148	        auto access = GetBlockReadWriteRegion(block, buffer_data_to_buffer_);
149	        std::set<const BufferNode *> read_set, write_set;
150	        for (auto region : access[0])
151	          read_set.insert(region->buffer.get());
152	        for (auto region : access[1])
153	          write_set.insert(region->buffer.get());
154	        if (intersect_fn(read_set, gemm_write_buffers_[r]) ||
155	            intersect_fn(write_set, gemm_read_buffers_[r]) ||
156	            intersect_fn(write_set, gemm_write_buffers_[r])) {
157	          break;
158	        }
159	        last_stmt = stmt_node->seq[i];
160	      }
161	      last_stmts_.push_back(last_stmt);
162	    }
163	
164	    auto new_seq = Array<Stmt>();
165	    for (int i = 0; i < static_cast<int>(stmt_node->seq.size()); i++) {
166	      bool remove_ = false;
