24	enum class Role : uint8_t { kConsumer, kProducer, kBoth };
25	
26	class WarpSpecializedRoleMarker_ : public StmtVisitor {
27	public:
28	  WarpSpecializedRoleMarker_(Map<Var, Buffer> buffer_data_to_buffer)
29	      : buffer_data_to_buffer_(std::move(buffer_data_to_buffer)) {}
30	
31	  Role GetRole(const StmtNode *stmt) const {
32	    auto it = map_.find(stmt);
33	    ICHECK(it != map_.end());
34	    return it->second;
35	  }
36	
37	  Role GetRole(const Stmt &stmt) const { return GetRole(stmt.get()); }
38	
39	  void VisitStmt_(const EvaluateNode *op) final {
40	    Role role = Role::kConsumer;
41	    if (auto call = op->value.as<CallNode>()) {
42	      if (call->op.same_as(tma_load()) || call->op.same_as(tma_load_im2col())) {
43	        role = Role::kProducer;
44	        has_bulk_copy_ = true;
45	      }
46	    }
47	    SetRole(op, role);
48	  }
49	
50	  void VisitStmt_(const BufferStoreNode *op) final {
51	    bool is_shared_store =
52	        op->buffer.scope() == "shared.dyn" || op->buffer.scope() == "shared";
53	    if (!is_shared_store) {
54	      SetRole(op, Role::kConsumer);
55	      return;
56	    }
57	
58	    // Check reads from global
59	    Block block(/*iter_vars=*/{}, /*reads=*/{}, /*writes=*/{}, /*name_hint=*/"",
60	                /*body*/ tvm::ffi::GetRef<Stmt>(op));
61	    auto access = GetBlockReadWriteRegion(block, buffer_data_to_buffer_);
62	    auto reads = access[0];
63	    Role role = Role::kProducer;
64	    for (auto read : reads) {
65	      if (read->buffer.scope() != "global") {
66	        role = Role::kConsumer;
67	        break;
68	      }
69	    }
70	    if (role == Role::kProducer)
71	      has_simt_copy_ = true;
72	    SetRole(op, role);
73	  }
74	
75	  void VisitStmt_(const SeqStmtNode *op) final {
76	    StmtVisitor::VisitStmt_(op);
77	    auto role = GetRole(op->seq[0]);
78	    for (auto stmt : op->seq) {
79	      if (role != GetRole(stmt)) {
80	        role = Role::kBoth;
81	        break;
82	      }
83	    }
84	    SetRole(op, role);
85	  }
86	
87	  void VisitStmt_(const IfThenElseNode *op) final {
88	    StmtVisitor::VisitStmt_(op);
89	    auto role = GetRole(op->then_case);
90	    if (op->else_case.defined()) {
91	      auto role_else = GetRole(op->else_case.value());
92	      if (role != role_else)
93	        role = Role::kBoth;
94	    }
95	    SetRole(op, role);
96	  }
97	
98	  void VisitStmt_(const BlockRealizeNode *op) final {
99	    StmtVisitor::VisitStmt_(op);
100	    SetRole(op, GetRole(op->block));
101	  }
102	
103	  template <class NodeType> void HandleBodyStmt(const NodeType *op) {
104	    StmtVisitor::VisitStmt_(op);
105	    SetRole(op, GetRole(op->body));
106	  }
107	
108	  void VisitStmt_(const ForNode *op) final { HandleBodyStmt(op); }
109	  void VisitStmt_(const LetStmtNode *op) final { HandleBodyStmt(op); }
110	  void VisitStmt_(const AttrStmtNode *op) final { HandleBodyStmt(op); }
111	  void VisitStmt_(const AssertStmtNode *op) final { HandleBodyStmt(op); }
112	  void VisitStmt_(const BlockNode *op) final { HandleBodyStmt(op); }
113	
114	  bool HasProducer() { return has_simt_copy_ || has_bulk_copy_; }
115	
116	  bool HasSimtCopy() { return has_simt_copy_; }
117	
118	private:
119	  void SetRole(const StmtNode *stmt, Role role) { map_[stmt] = role; }
120	  Map<Var, Buffer> buffer_data_to_buffer_;
121	  std::unordered_map<const StmtNode *, Role> map_;
122	  bool has_simt_copy_ = false;
123	  bool has_bulk_copy_ = false;
124	};
125	
126	class MultiVersionBufferRewriter : public StmtExprMutator {
127	public:
128	  static PrimFunc Substitute(PrimFunc &f) {
129	    auto rewriter = MultiVersionBufferRewriter();
130	    rewriter.buffer_lca_ = DetectBufferAccessLCA(f);
131	    for (auto [buffer, _] : rewriter.buffer_lca_) {
132	      Var buffer_var = buffer->data;
133	      rewriter.buffer_data_to_buffer_.Set(buffer_var, buffer);
134	    }
135	    f.CopyOnWrite()->body = rewriter(f->body);
136	    return f;
137	  }
138	
139	private:
140	  MultiVersionBufferRewriter() = default;
141	
142	  Array<Buffer> GetVersionedBuffers(const Array<Stmt> &seq_stmt,
143	                                    const Array<Buffer> &scoped_buffers) {
144	    Array<Stmt> pipeline_stmts;
145	    std::function<void(const Stmt &)> collect_stmts = [&](const Stmt &stmt) {
146	      if (const auto *seq = stmt.as<SeqStmtNode>()) {
147	        for (const Stmt &s : seq->seq) {
148	          collect_stmts(s);
149	        }
150	        return;
151	      }
152	      if (const auto *let = stmt.as<LetStmtNode>()) {
153	        collect_stmts(let->body);
154	        return;
155	      }
156	      if (const auto *attr = stmt.as<AttrStmtNode>()) {
157	        collect_stmts(attr->body);
158	        return;
159	      }
160	      if (const auto *block_realize = stmt.as<BlockRealizeNode>()) {
161	        collect_stmts(block_realize->block->body);
162	        return;
163	      }
164	      if (const auto *block = stmt.as<BlockNode>()) {
165	        collect_stmts(block->body);
166	        return;
167	      }
168	      pipeline_stmts.push_back(stmt);
169	    };
170	    for (const Stmt &stmt : seq_stmt) {
171	      collect_stmts(stmt);
172	    }
173	
174	    std::vector<Role> roles;
175	    Array<Array<BufferRegion>> reads, writes;
176	    auto marker = WarpSpecializedRoleMarker_(buffer_data_to_buffer_);
177	    for (const Stmt &stmt : pipeline_stmts) {
178	      marker(stmt);
179	      Block block(/*iter_vars=*/{}, /*reads=*/{}, /*writes=*/{},
180	                  /*name_hint=*/"", /*body*/ stmt);
181	      auto access = GetBlockAccessRegion(block, buffer_data_to_buffer_);
182	      reads.push_back(access[0]);
183	      writes.push_back(access[1]);
184	      roles.push_back(marker.GetRole(stmt));
185	    }
186	
187	    std::unordered_set<const BufferNode *> consumer_used, producer_used;
188	    std::unordered_map<const BufferNode *, size_t> first_write_index;
189	    std::unordered_map<const BufferNode *, size_t> last_read_index;
190	    auto is_copy_stage = [&](size_t idx) {
191	      bool has_shared_write = false;
192	      for (const BufferRegion &wr : writes[idx]) {
193	        auto scope = wr->buffer.scope();
194	        if (scope == "shared" || scope == "shared.dyn") {
195	          has_shared_write = true;
196	          break;
197	        }
198	      }
199	      if (!has_shared_write)
200	        return false;
201	      for (const BufferRegion &rd : reads[idx]) {
202	        if (rd->buffer.scope() == "global") {
203	          return true;
204	        }
205	      }
206	      return false;
207	    };
208	    for (size_t i = 0; i < pipeline_stmts.size(); i++) {
209	      bool copy_stage = is_copy_stage(i);
210	      bool is_producer = roles[i] == Role::kProducer ||
211	                         (roles[i] == Role::kBoth && copy_stage);
212	      bool is_consumer = roles[i] == Role::kConsumer ||
213	                         (roles[i] == Role::kBoth && !copy_stage);
214	      if (is_producer) {
215	        for (BufferRegion br : writes[i]) {
216	          producer_used.insert(br->buffer.get());
217	        }
218	      }
219	      if (is_consumer) {
220	        for (BufferRegion br : reads[i]) {
221	          consumer_used.insert(br->buffer.get());
222	        }
223	      }
224	      for (BufferRegion br : writes[i]) {
225	        const BufferNode *buf = br->buffer.get();
226	        if (!first_write_index.count(buf)) {
227	          first_write_index[buf] = i;
228	        }
229	      }
230	      for (BufferRegion br : reads[i]) {
231	        last_read_index[br->buffer.get()] = i;
232	      }
233	    }
234	    Array<Buffer> versioned_buffers;
235	    for (Buffer buffer : scoped_buffers) {
236	      if (consumer_used.count(buffer.get()) &&
237	          producer_used.count(buffer.get())) {
238	        versioned_buffers.push_back(buffer);
239	        continue;
240	      }
241	      // Fallback: if we saw a write before a later read, the buffer spans
242	      // multiple stages even if role classification missed one side.
243	      auto it_w = first_write_index.find(buffer.get());
244	      auto it_r = last_read_index.find(buffer.get());
245	      if (it_w != first_write_index.end() && it_r != last_read_index.end() &&
246	          it_w->second < it_r->second) {
247	        if (!is_copy_stage(it_w->second))
248	          continue;
249	        versioned_buffers.push_back(buffer);
250	      }
251	    }
252	    return versioned_buffers;
253	  }
254	
255	  static Buffer RewriteAllocBuffer(const Buffer &buffer, int num_versions) {
256	    ObjectPtr<BufferNode> new_buffer =
257	        tvm::ffi::make_object<BufferNode>(*(buffer.get()));
258	    new_buffer->shape.insert(new_buffer->shape.begin(), PrimExpr(num_versions));
259	    if (!new_buffer->strides.empty()) {
260	      ICHECK(new_buffer->strides.size() + 1 == new_buffer->shape.size());
261	      PrimExpr stride_0 = new_buffer->strides[0] * new_buffer->shape[1];
262	      new_buffer->strides.insert(new_buffer->strides.begin(), stride_0);
263	    }
264	    return Buffer(new_buffer);
265	  }
266	
267	  Stmt VisitStmt_(const BlockRealizeNode *op) final {
268	    BlockRealize block_realize =
269	        Downcast<BlockRealize>(StmtExprMutator::VisitStmt_(op));
270	    Block block = block_realize->block;
271	    Array<Buffer> alloc_buffers;
272	    for (auto buffer : block->alloc_buffers) {
273	      if (buffer_remap_.count(buffer)) {
274	        Buffer new_buffer = buffer_remap_[buffer];
275	        alloc_buffers.push_back(new_buffer);
276	      } else {
277	        alloc_buffers.push_back(buffer);
278	      }
279	    }
280	    block.CopyOnWrite()->alloc_buffers = std::move(alloc_buffers);
281	    // Record the updated alloc list to recover buffers whose LCA is the block.
282	    block_alloc_buffers_[op->block.get()] = block->alloc_buffers;
283	    block_realize.CopyOnWrite()->block = block;
284	    return block_realize;
285	  }
286	
287	  Stmt VisitStmt_(const BlockNode *op) final {
288	    stmt_stack_.push_back(op);
289	    Stmt stmt = StmtExprMutator::VisitStmt_(op);
290	    stmt_stack_.pop_back();
291	    return stmt;
292	  }
293	
294	  Stmt VisitStmt_(const ForNode *op) final {
295	    stmt_stack_.push_back(op);
296	    loop_stack_.emplace_back(op->loop_var, op->extent);
297	    auto num_stages_anno = op->annotations.Get("num_stages");
298	    if (!num_stages_anno) {
299	      auto for_node = StmtExprMutator::VisitStmt_(op);
300	      loop_stack_.pop_back();
301	      stmt_stack_.pop_back();
302	      return for_node;
303	    }
304	
305	    ICHECK(num_stages_anno->as<IntImmNode>());
306	    int num_stages = static_cast<int>(num_stages_anno->as<IntImmNode>()->value);
307	
308	    Stmt pipeline_body_root{nullptr};
309	    if (const auto *realize = op->body.as<BlockRealizeNode>()) {
310	      const auto &block = realize->block;
311	      for (const auto &buffer : block->alloc_buffers) {
312	        ICHECK(buffer->IsInstance<BufferNode>());
313	        buffer_data_to_buffer_.Set(buffer->data, buffer);
314	      }
315	      pipeline_body_root = block->body;
316	    } else {
317	      pipeline_body_root = op->body;
318	    }
319	
320	    const SeqStmtNode *pipeline_body_seq = nullptr;
321	    {
322	      // Traverse trivial wrappers (let/if) to find the actual SeqStmt body.
323	      Stmt current = pipeline_body_root;
324	      while (true) {
325	        if (const auto *seq_stmt = current.as<SeqStmtNode>()) {
326	          pipeline_body_seq = seq_stmt;
327	          break;
328	        }
329	        if (const auto *if_then_else = current.as<IfThenElseNode>()) {
330	          ICHECK(!if_then_else->else_case.defined())
331	              << "MultiVersionBuffer: Can't handle the body of the loop "
332	                 "because the IfThenElse node has an else branch";
333	          current = if_then_else->then_case;
334	          continue;
335	        }
336	        if (const auto *let_stmt = current.as<LetStmtNode>()) {
337	          current = let_stmt->body;
338	          continue;
339	        }
340	        LOG(FATAL)
341	            << "MultiVersionBuffer: Can't handle the body of the loop because "
342	            << "it is not a SeqStmt, IfThenElse without else, "
343	            << "or LetStmt wrapping them, but got " << current->GetTypeKey();
344	      }
345	    }
346	    ICHECK(pipeline_body_seq != nullptr);
347	
348	    Array<Buffer> scoped_buffers;
349	    std::unordered_set<const BufferNode *> seen;
350	    for (auto [buffer, stmt] : buffer_lca_) {
351	      if (!stmt.defined())
352	        continue;
353	      const StmtNode *lca = stmt.value().get();
354	      bool in_scope = false;
355	      for (const StmtNode *ancestor : stmt_stack_) {
356	        if (ancestor == lca) {
357	          in_scope = true;
358	          break;
359	        }
360	      }
361	      if (!in_scope)
362	        continue;
363	      // Only double-buffer shared allocations; locals do not need versioning.
364	      auto scope = buffer.scope();
365	      if (!(scope == "shared" || scope == "shared.dyn"))
366	        continue;
367	      if (seen.insert(buffer.get()).second) {
368	        scoped_buffers.push_back(buffer);
369	      }
370	    }
371	    for (auto it = stmt_stack_.rbegin(); it != stmt_stack_.rend(); ++it) {
372	      if (!(*it)->IsInstance<BlockNode>())
373	        continue;
374	      const auto *block = static_cast<const BlockNode *>(*it);
375	      auto map_it = block_alloc_buffers_.find(block);
376	      if (map_it == block_alloc_buffers_.end())
377	        continue;
378	      for (const Buffer &buffer : map_it->second) {
379	        auto scope = buffer.scope();
380	        if (!(scope == "shared" || scope == "shared.dyn"))
381	          continue;
382	        if (seen.insert(buffer.get()).second) {
383	          scoped_buffers.push_back(buffer);
384	        }
385	      }
386	    }
387	
388	    Array<Buffer> versioned_buffers =
389	        GetVersionedBuffers(pipeline_body_seq->seq, scoped_buffers);
390	
391	    for (auto buffer : versioned_buffers) {
392	      Var buffer_var = buffer->data;
393	      Buffer new_buffer = RewriteAllocBuffer(buffer, num_stages);
394	      buffer_remap_.Set(buffer, new_buffer);
395	    }
396	    PrimExpr linear_index = loop_stack_[0].first;
397	    for (size_t i = 1; i < loop_stack_.size(); ++i) {
398	      linear_index =
399	          linear_index * loop_stack_[i].second + loop_stack_[i].first;
400	    }
401	    version_index_ = FloorMod(linear_index, num_stages);
402	    auto for_node = StmtExprMutator::VisitStmt_(op);
403	    loop_stack_.pop_back();
404	    stmt_stack_.pop_back();
405	
406	    return for_node;
407	  }
408	
409	  PrimExpr VisitExpr_(const BufferLoadNode *op) final {
410	    BufferLoad load = Downcast<BufferLoad>(StmtExprMutator::VisitExpr_(op));
411	    auto it = buffer_remap_.find(load->buffer);
412	    if (it == buffer_remap_.end()) {
413	      return std::move(load);
414	    }
415	    const Buffer &new_buffer = (*it).second;
416	    auto *n = load.CopyOnWrite();
417	    n->buffer = new_buffer;
418	    n->indices.insert(n->indices.begin(), version_index_);
419	    return std::move(load);
420	  }
421	
422	  Stmt VisitStmt_(const BufferStoreNode *op) final {
423	    BufferStore store = Downcast<BufferStore>(StmtExprMutator::VisitStmt_(op));
424	    auto it = buffer_remap_.find(store->buffer);
425	    if (it == buffer_remap_.end()) {
426	      return std::move(store);
427	    }
428	    const Buffer &new_buffer = (*it).second;
429	    auto *n = store.CopyOnWrite();
430	    n->buffer = new_buffer;
431	    n->indices.insert(n->indices.begin(), version_index_);
432	    return std::move(store);
433	  }
434	
435	  PrimExpr VisitExpr_(const CallNode *op) final {
436	    Call call = Downcast<Call>(StmtExprMutator::VisitExpr_(op));
437	    if (call->op.same_as(builtin::tvm_access_ptr())) {
438	      return RewriteBufferAccess(call, {1});
439	    }
440	    return call;
441	  }
442	
443	  PrimExpr RewriteBufferAccess(const Call &call,
444	                               const std::vector<int> &arg_indices) {
445	    auto product = [](const Array<PrimExpr> &input) {
446	      return foldl(
447	          [](PrimExpr a, PrimExpr b, Span span) {
448	            return mul(std::move(a), std::move(b), std::move(span));
449	          },
450	          make_const(DataType::Int(32), 1), input);
451	    };
452	    Array<PrimExpr> new_args = call->args;
453	    for (int i : arg_indices) {
454	      auto buffer_var = Downcast<Var>(call->args[i]);
455	      if (!buffer_data_to_buffer_.count(buffer_var))
456	        continue;
457	      const Buffer &buffer = buffer_data_to_buffer_[buffer_var];
458	      auto it = buffer_remap_.find(buffer);
459	      if (it != buffer_remap_.end()) {
460	        const Buffer &new_buffer = (*it).second;
461	        const PrimExpr &old_index = call->args[i + 1];
462	        PrimExpr offset;
463	        if (new_buffer->strides.empty()) {
464	          offset = product(buffer->shape);
465	        } else {
466	          offset = new_buffer->strides[0];
467	        }
468	        PrimExpr new_index = old_index + version_index_ * offset;
469	        new_args.Set(i + 1, new_index);
470	      }
471	    }
472	    return Call(call->dtype, call->op, new_args, call->annotations, call->span);
473	  }
474	
475	  PrimExpr version_index_;
476	  std::vector<std::pair<Var, PrimExpr>> loop_stack_;
477	  // Track ancestor statements to query whether an LCA is inside the current
478	  // loop.
479	  std::vector<const StmtNode *> stmt_stack_;
480	  Map<Var, Buffer> buffer_data_to_buffer_;
481	  Map<Buffer, Optional<Stmt>> buffer_lca_;
482	  Map<Buffer, Buffer> buffer_remap_;
483	  // Remember each block's alloc list so the loop can see buffers defined in
484	  // parents.
485	  std::unordered_map<const BlockNode *, Array<Buffer>> block_alloc_buffers_;
486	};
487	
488	using namespace tir::transform;
489	
490	tvm::transform::Pass MultiVersionBuffer() {
491	  auto pass_func = [=](PrimFunc f, const IRModule &m, const PassContext &ctx) {
492	    return MultiVersionBufferRewriter::Substitute(f);
493	  };
494	  return CreatePrimFuncPass(pass_func, 0, "tl.MultiVersionBuffer", {});
495	}
496	
497	TVM_FFI_STATIC_INIT_BLOCK() {
498	  namespace refl = tvm::ffi::reflection;
499	  refl::GlobalDef().def("tl.transform.MultiVersionBuffer", MultiVersionBuffer);
500	}
501	
502	} // namespace tl
503	} // namespace tvm
